#include "dfre/mission_df_host_controls.hpp"
#include <array>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace {using U=std::uint32_t;constexpr U sites[]={0x4b91c0,0x4b92f0,0x4b9300,0x4b93d0};constexpr U sizes[]={0x130,4,0xa8,4};
struct Test {std::array<U,24>row{};std::vector<std::uint8_t>df=std::vector<std::uint8_t>(0xa00000),data=std::vector<std::uint8_t>(0x100000),stack=std::vector<std::uint8_t>(0x1000);U reads=0,writes=0,calls=0;std::uint64_t trace=0,payload=0;U f=0x3000000,n=0;
std::uint8_t*ptr(U a,U count){if(a>=0x400000&&std::uint64_t(a-0x400000)+count<=df.size())return df.data()+a-0x400000;if(a>=0x1200000&&std::uint64_t(a-0x1200000)+count<=data.size())return data.data()+a-0x1200000;if(a>=f&&std::uint64_t(a-f)+count<=n)return stack.data()+a-f;throw std::runtime_error("DF control address is not mapped");}
U get(U a,U count=4){U v=0;for(U i=0;i<count;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;}void put(U a,U v,U count=4){for(U i=0;i<count;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));}U norm(U a){return a>=f&&a<f+n?0x30000000+a-f:a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}bool mapped(U a,U count,bool store=false){try{ptr(a,count);}catch(...){return false;}const U gap=row[0]==0?0x100:row[0]==2?0x88:0;if(store&&gap&&a<f+gap+16&&std::uint64_t(a)+count>f+gap)return false;return true;}
void string(U a,U count,char start){for(U i=0;i<count;++i)put(a+i,start+i%23,1);put(a+count,0,1);}void setup(){n=sizes[row[0]];std::fill(df.begin(),df.end(),0x5a);std::fill(data.begin(),data.end(),0x5a);std::fill(stack.begin(),stack.end(),0x5a);trace=1469598103934665603ull;payload=0;reads=writes=calls=0;put(0x501320,row[1]);put(0x50133c,0xdeadbeef);put(0x501340,0xabcdef01);put(0x501368,0);string(0x1200000,row[2],'A');string(0x1201000,3,'a');string(0x1202000,row[3]==0xffffffffu?2:row[3],'p');string(0x1203000,4,'k');for(U i=0;i<4;++i)put(0x4cebc4+i*4,0x11223344u+i*0x11111111u);const U gap=row[0]==0?0x100:row[0]==2?0x88:0;if(gap){put(f+gap,row[12]);put(f+gap+4,row[13]);put(f+gap+8,row[14]);put(f+gap+12,0x4000000);}if(row[0]==0){put(f+0x110,row[15]==1?f+0x10:row[15]==2?0:0x1200000);put(f+0x118,row[17]);put(f+0x11c,row[3]==0xffffffffu?0:row[16]?f+0x90:0x1202000);for(U i=0;i<4;++i)put(f+0x120+i*4,row[18+i]);}else if(row[0]==2){put(f+0x98,row[15]==1?f:row[15]==2?0:0x1200000);put(f+0x9c,row[4]);put(f+0xa0,row[11]?f+0x10:0x1204000);put(f+0xa4,row[5]);}}
dfre::MissionGameTransportBindings bindings(){dfre::MissionGameTransportBindings b;b.read=[&](U a,U count){if(std::getenv("DFRE_TRACE"))std::cerr<<"R "<<norm(a)<<" "<<count<<'\n';event(1);event(norm(a));event(count);if(++reads==row[8]||!mapped(a,count))throw std::runtime_error("Read failure");if((row[7]&4)&&a==0x4cebc4){put(f+0x110,0x1201000);put(0x4cebcc,0xdecafbad);}if((row[7]&64)&&a==0x50133c)put(0x50133c,row[22]+2);return get(a,count);};
b.write=[&](U a,U count,U value){if(std::getenv("DFRE_TRACE"))std::cerr<<"W "<<norm(a)<<" "<<count<<" "<<norm(value)<<'\n';event(2);event(norm(a));event(count);event(norm(count==4?value:value&((1u<<(8*count))-1)));if(++writes==row[9]||!mapped(a,count,true))throw std::runtime_error("Write failure");put(a,value,count);};
b.before_call=[&](U s,const auto&args){if(std::getenv("DFRE_TRACE")){std::cerr<<"C "<<s;for(U v:args)std::cerr<<" "<<norm(v);std::cerr<<'\n';}event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[10])throw std::runtime_error("Call failure");if(s==0x49a620){if(row[7]&1){if(row[0]==0){put(f+0x118,13);put(f+0x110,0x1201000);put(f+0x11c,0x1203000);}else if(row[0]==2)put(f+0x9c,!row[4]);}if((row[7]&2)&&row[0]==2){put(f+0x98,0x1201000);put(f+0xa0,0x1205000);put(f+0xa4,3);}if(row[7]&128)put(0x501320,0);}if(s==0x4c5538&&(row[7]&8))put(0x501368,77);if(s==0x4c552c){if(row[7]&16)put(f+0x9c,1);if(row[7]&32)put(f+0x9c,0);}};
b.call=[&](U s,const auto&args)->U{if(s==0x49a620){for(U i=0;i<args[2];++i){if(!mapped(args[0]+i,1,true))throw std::runtime_error("Clear provider range failure");put(args[0]+i,args[1]&255,1);}return args[0];}if(s==0x4c5538||s==0x4c552c){const U at=s==0x4c5538?args[0]:args[1],count=s==0x4c5538?0x100:0x98;payload=1469598103934665603ull;for(U i=0;i<count;++i){U value=get(at+i,1);if(s==0x4c552c&&i>=0x80&&i<0x84)value=(norm(get(at+0x80))>>(8*(i-0x80)))&255;payload^=value;payload*=1099511628211ull;}if(s==0x4c552c)put(args[0],row[22]);return row[6];}if(s==0x4c5526||s==0x4c5532)return row[6];throw std::runtime_error("DF control required service is not bound");};return b;}
};}
int main(){Test t;std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream input(line);for(U&v:t.row)if(!(input>>v))return 2;t.setup();auto b=t.bindings();bool failed=false;U result=0;try{result=dfre::mission_df_host_control_call(b,sites[t.row[0]],t.f);}catch(const std::runtime_error&){failed=true;}if(failed)result=0;std::uint64_t state=1469598103934665603ull;for(auto[a,count]:std::vector<std::pair<U,U>>{{0x501320,0x80},{0x4cebc4,16},{0x1200000,0x6000},{t.f,t.row[0]==0?0x110u:t.row[0]==2?0x98u:0u}})for(U i=0;i<count;++i){U value=t.get(a+i,1);if(t.row[0]==2&&a==t.f&&i>=0x80&&i<0x84)value=(t.norm(t.get(t.f+0x80))>>(8*(i-0x80)))&255;state^=value;state*=1099511628211ull;}std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<t.payload<<' '<<state<<'\n';}}
